package com.birdhouse.tracker;

import java.awt.Color;
import java.awt.TrayIcon;
import javax.inject.Inject;
import net.runelite.api.ChatMessageType;
import net.runelite.client.Notifier;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.FlashNotification;
import net.runelite.client.config.Notification;
import net.runelite.client.config.NotificationSound;
import net.runelite.client.config.RequestFocusType;

/** READY delivery channels, shared by live events and founder-only smoke tests. */
final class BirdhouseNotificationDelivery
{
    static final Color CHAT_RED = new Color(255, 0, 0);
    // Explicitly desktop-only to avoid the second, default-highlight chat message
    // that RuneLite's generic notifier can otherwise generate.
    private static final Notification DESKTOP_ONLY = new Notification(
        true, true, true, true, TrayIcon.MessageType.INFO,
        RequestFocusType.OFF, NotificationSound.OFF, null, 0, 0,
        false, FlashNotification.DISABLED, CHAT_RED, true);

    private final ChatMessageManager chatMessageManager;
    private final Notifier notifier;

    @Inject
    BirdhouseNotificationDelivery(ChatMessageManager chatMessageManager, Notifier notifier)
    {
        this.chatMessageManager = chatMessageManager;
        this.notifier = notifier;
    }

    void sendReady()
    {
        // Both calls use the same literal text. The two paths are deliberately
        // independent and can be smoke-tested separately.
        try
        {
            sendRedChat();
        }
        finally
        {
            // Even if chat queuing fails, still attempt desktop delivery.
            sendDesktop();
        }
    }

    void sendRedChat()
    {
        String formatted = new ChatMessageBuilder()
            .append(CHAT_RED, BirdhouseWarningMessage.READY_TEXT)
            .build();
        chatMessageManager.queue(QueuedMessage.builder()
            .type(ChatMessageType.CONSOLE)
            .runeLiteFormattedMessage(formatted)
            .build());
    }

    void sendDesktop()
    {
        notifier.notify(DESKTOP_ONLY, BirdhouseWarningMessage.READY_TEXT);
    }
}

package com.birdhouse.tracker;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.time.Instant;
import java.util.List;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/** Movable game-screen overlay for active sites, with an explicit empty state. */
final class BirdhouseOverlay extends OverlayPanel
{
    static final int COMPACT_WIDTH_PX = 190;
    static final String EMPTY_STATE_MESSAGE = "No active birdhouses";
    static final Color READY_COLOR = new Color(110, 230, 130);
    static final Color SOON_COLOR = new Color(255, 220, 50);
    static final Color GROWING_COLOR = new Color(255, 80, 80);

    private final BirdhouseTrackerPlugin plugin;
    private final BirdhouseTrackerConfig config;

    @Inject
    BirdhouseOverlay(BirdhouseTrackerPlugin plugin, BirdhouseTrackerConfig config)
    {
        super(plugin);
        this.plugin = plugin;
        this.config = config;
        setPosition(OverlayPosition.TOP_LEFT);
        setPriority(PRIORITY_MED);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        List<BirdhouseTimer> timers = plugin.getTimers();
        panelComponent.setPreferredSize(new Dimension(COMPACT_WIDTH_PX, 0));
        panelComponent.getChildren().add(TitleComponent.builder()
            .text(config.demoMode() ? "Birdhouses [DEMO]" : "Birdhouses")
            .build());

        if (timers.isEmpty())
        {
            panelComponent.getChildren().add(LineComponent.builder()
                .left(EMPTY_STATE_MESSAGE)
                .build());
            return super.render(graphics);
        }

        long now = Instant.now().getEpochSecond();
        for (BirdhouseTimer timer : timers)
        {
            long remaining = timer.secondsRemaining(now);
            Color statusColor = statusColor(remaining, config.warningLeadTime());
            String label = timer.site.displayLabel();
            panelComponent.getChildren().add(LineComponent.builder()
                .left(label)
                .right(timer.display(now))
                .rightColor(statusColor)
                .build());
        }
        return super.render(graphics);
    }

    /** The existing advance-warning preference also controls the yellow visual cue. */
    static Color statusColor(long remainingSeconds, WarningLeadTime leadTime)
    {
        if (remainingSeconds <= 0)
        {
            // READY denotes the 50-minute estimate, not confirmed maturity.
            return READY_COLOR;
        }
        int warningMinutes = leadTime == null ? 0 : leadTime.minutes;
        return warningMinutes > 0 && remainingSeconds <= warningMinutes * 60L
            ? SOON_COLOR : GROWING_COLOR;
    }
}

package com.birdhouse.tracker;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import net.runelite.api.gameval.VarPlayerID;

/** The four Fossil Island birdhouse spaces as named by RuneLite Time Tracking. */
enum BirdhouseSite
{
    MEADOW_NORTH("Mushroom Meadow North", VarPlayerID.BIRDHOUSE_TRANSMIT_A),
    MEADOW_SOUTH("Mushroom Meadow South", VarPlayerID.BIRDHOUSE_TRANSMIT_B),
    VALLEY_NORTH("Verdant Valley NE", VarPlayerID.BIRDHOUSE_TRANSMIT_C),
    VALLEY_SOUTH("Verdant Valley SW", VarPlayerID.BIRDHOUSE_TRANSMIT_D);

    // Intentionally separate from enum declaration order so varp and persisted
    // notification identity remain stable. Never sort rows by maturity.
    private static final List<BirdhouseSite> DISPLAY_ORDER = Collections.unmodifiableList(
        Arrays.asList(MEADOW_SOUTH, MEADOW_NORTH, VALLEY_SOUTH, VALLEY_NORTH));

    final String label;
    final int varp;

    BirdhouseSite(String label, int varp)
    {
        this.label = label;
        this.varp = varp;
    }

    static List<BirdhouseSite> displayOrder()
    {
        return DISPLAY_ORDER;
    }

    /** Ceci's location label for the single compact overlay. */
    String displayLabel()
    {
        return label;
    }
}

package com.birdhouse.tracker;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/** A read-only interpretation of RuneLite's per-site Time Tracking record. */
final class BirdhouseTimer
{
    static final long MATURITY_SECONDS = 50 * 60L;
    private static final long EARLIEST_REASONABLE_TIMESTAMP = 1_500_000_000L;
    private static final long MAX_FUTURE_CLOCK_SKEW_SECONDS = 60 * 60L;

    final BirdhouseSite site;
    final int varpValue;
    final long plantedAt;
    final String cycleKey;

    private BirdhouseTimer(BirdhouseSite site, int varpValue, long plantedAt)
    {
        this.site = site;
        this.varpValue = varpValue;
        this.plantedAt = plantedAt;
        this.cycleKey = varpValue + ":" + plantedAt;
    }

    /** Return null for empty, built-but-unseeded, missing, or invalid states. */
    static BirdhouseTimer parse(BirdhouseSite site, String stored, long nowSeconds)
    {
        if (stored == null)
        {
            return null;
        }

        String[] parts = stored.split(":", -1);
        if (parts.length != 2)
        {
            return null;
        }

        try
        {
            int varp = Integer.parseInt(parts[0]);
            long timestamp = Long.parseLong(parts[1]);
            // RuneLite: positive, every third birdhouse value means it is seeded.
            // Nine birdhouse tiers, three states per tier.
            if (varp <= 0 || varp > 27 || varp % 3 != 0
                || timestamp < EARLIEST_REASONABLE_TIMESTAMP
                || timestamp > nowSeconds + MAX_FUTURE_CLOCK_SKEW_SECONDS)
            {
                return null;
            }
            return new BirdhouseTimer(site, varp, timestamp);
        }
        catch (NumberFormatException ex)
        {
            return null;
        }
    }

    /**
     * Purely illustrative countdowns. Demo values are never stored in RuneLite
     * configuration and never represent a player's actual birdhouses.
     */
    static List<BirdhouseTimer> demoTimers(long startedAt)
    {
        // READY, 4 minutes, 15 minutes and 42 minutes at demo start.
        int[] secondsAlreadyElapsed = {55 * 60, 46 * 60, 35 * 60, 8 * 60};
        List<BirdhouseSite> sites = BirdhouseSite.displayOrder();
        List<BirdhouseTimer> result = new ArrayList<>(sites.size());
        for (int i = 0; i < sites.size(); i++)
        {
            // "3" is a seeded tier in RuneLite's birdhouse varp encoding.
            BirdhouseTimer timer = parse(sites.get(i), "3:" + (startedAt - secondsAlreadyElapsed[i]), startedAt);
            if (timer != null)
            {
                result.add(timer);
            }
        }
        return Collections.unmodifiableList(result);
    }

    long secondsRemaining(long nowSeconds)
    {
        return plantedAt + MATURITY_SECONDS - nowSeconds;
    }

    String display(long nowSeconds)
    {
        long remaining = secondsRemaining(nowSeconds);
        if (remaining <= 0)
        {
            return "READY";
        }
        long minutes = remaining / 60;
        long seconds = remaining % 60;
        return String.format(java.util.Locale.ROOT, "%02d:%02d", minutes, seconds);
    }
}

